using System;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Json;
using System.Windows;
using System.Windows.Media.Imaging;

namespace MaohaiziPet {
public static class JumpPlayTests {
    static LivingReport report;
    static void Assert(bool ok,string text){if(!ok)throw new Exception(text);}
    static void Check(string name,Action run){var t=new TestResult{name=name};try{run();t.passed=true;report.passed++;}catch(Exception e){t.error=e.ToString();report.failed++;}report.tests.Add(t);}
    static void Step(PetController c,double dt){ToyInteractionTests.Step(c,dt);}
    static void Observe(PetController c,Point p){c.ObserveTool(ToyInteractionTests.Local(c,p),true);}
    static byte[] Pixels(BitmapSource f){var v=new byte[f.PixelWidth*f.PixelHeight*4];f.CopyPixels(v,f.PixelWidth*4,0);return v;}
    static Rect Ink(BitmapSource f){byte[] v=Pixels(f);int x0=f.PixelWidth,y0=f.PixelHeight,x1=-1,y1=-1;for(int y=0;y<f.PixelHeight;y++)for(int x=0;x<f.PixelWidth;x++)if(v[(y*f.PixelWidth+x)*4+3]>=128){x0=Math.Min(x0,x);x1=Math.Max(x1,x);y0=Math.Min(y0,y);y1=Math.Max(y1,y);}return new Rect(x0,y0,x1-x0+1,y1-y0+1);}
    static Point Goal(MotionClip clip){int at=Enumerable.Range(clip.Spec.contactStart,clip.Spec.contactEnd-clip.Spec.contactStart+1).OrderBy(i=>clip.Spec.pawY[i]).First();return new Point(Math.Max(85,Math.Min(195,clip.Spec.pawX[at]+clip.Spec.originX)),Math.Max(-115,Math.Min(135,clip.Spec.pawY[at]+clip.Spec.originY+10)));}
    static void Start(PetController c,Point target){ToyInteractionTests.Pose(c,CatHabit.SitUp);c.SelectTool(PetTool.Feather);for(int i=0;i<100&&c.Life.Play.Jumps==0;i++){Step(c,.02);Observe(c,new Point(target.X+Math.Sin(i*.5)*12,target.Y));}Assert(c.Life.Play.Jumps==1&&c.Skin.Motion.PostureActivity=="sit-jump","高处羽毛没有启动原生扑抓");}
    public static int Run(string manifest,string output){
        Directory.CreateDirectory(output);PetSettings.UsePreviewProfile(Path.Combine(output,"isolated-"+Guid.NewGuid().ToString("N")));report=new LivingReport{scope="High feather reach, one jump per lift, native airborne/landing continuity, contact and viewport constraints"};
        Check("高低羽毛分别进入起跳与拨爪入口",delegate{int jumps=0,paws=0;var p=new PetPlaySession{RequestJump=q=>{jumps++;return true;},RequestPaw=left=>{paws++;return true;}};p.Select(PetTool.Feather);p.Observe(new Point(120,90),true);p.Observe(new Point(145,90),true);Assert(jumps==1&&p.Jumps==1&&paws==0,"高目标仍按低处拨爪");p.Select(PetTool.Feather);p.Observe(new Point(145,220),true);p.Observe(new Point(170,220),true);Assert(paws==1,"低处入口丢失");});
        Check("静止羽毛和超出可达范围的目标不触发原地反复跳",delegate{var p=new PetPlaySession{RequestJump=q=>true};p.Select(PetTool.Feather);for(int i=0;i<300;i++){p.Tick(.03);p.Observe(new Point(140,70),true);}Assert(p.Jumps==0,"静止羽毛刷跳跃");foreach(var q in new[]{new Point(140,-1000),new Point(900,60),new Point(double.NaN,0)})p.Observe(q,true);Assert(p.Jumps==0,"不合法或够不到的目标触发跳跃");});
        Check("同一次举高只跳一次，放低后重新举高才能再跳",delegate{var p=new PetPlaySession{RequestJump=q=>true,RequestPaw=left=>false};p.Select(PetTool.Feather);for(int i=0;i<700;i++){p.Tick(.02);p.Observe(new Point(140+Math.Sin(i)*15,85),true);}Assert(p.Jumps==1,"同一高处目标连续循环跳跃");p.Observe(new Point(140,210),true);p.Tick(.05);p.Observe(new Point(120,85),true);p.Observe(new Point(145,85),true);Assert(p.Jumps==2,"重新举高无法再次互动");});
        Check("无可用原生素材或玩毛线球时不会虚构起跳",delegate{var p=new PetPlaySession{RequestJump=q=>false};p.Select(PetTool.Feather);p.Observe(new Point(120,80),true);p.Observe(new Point(150,80),true);Assert(p.Jumps==0,"拒绝素材仍计数");p.Select(PetTool.Yarn);p.Observe(new Point(120,80),true);p.Observe(new Point(150,80),true);Assert(p.Jumps==0,"球进入高羽毛流程");});
        var app=new Application();var c=ToyInteractionTests.Create(manifest);var clip=c.Skin.Motions.Clips["sit-jump"];Point target=Goal(clip);
        Check("完整原生动作包含四爪腾空，且回到同一坐姿",delegate{Assert(clip.Size==576&&clip.Spec.physicalTransitionReviewed&&clip.Spec.transitionSource=="continuous-video","不是已审连续原生素材");Assert(MotionLibrary.SamePose(clip.Frames[0],c.Skin.Motions.Clips["sit"].Frames[c.Skin.Motions.Clips["sit"].Spec.holdAt])&&MotionLibrary.SamePose(clip.Frames.Last(),clip.Frames[0]),"起落换了姿势");double floor=235-clip.Spec.originY;int off=0;for(int i=clip.Spec.airborneStart;i<=clip.Spec.airborneEnd;i++)if(Ink(clip.Frames[i]).Bottom<floor-8)off++;Assert(off>=6,"没有足够连续的全身离地帧");Assert(Math.Abs(Ink(clip.Frames[clip.Frames.Length-1]).Bottom-1-floor)<=1,"落地支撑未回到原地");});
        Check("实际坐姿输入启动跳跃，原桌面坐标保持不动",delegate{Start(c,target);Assert(c.Pet.Surface.ToolRect.Contains(ToyInteractionTests.Local(c,target)),"空中目标在真实鼠标输入区域外");Point root=new Point(c.Pet.Left,c.Pet.Top);bool seenAir=false;for(int i=0;i<600&&c.Skin.Motion.PostureActivity!=null;i++){Step(c,.01);Assert(new Point(c.Pet.Left,c.Pet.Top)==root,"把整张图片窗口上移冒充跳跃");seenAir|=c.Skin.Motion.ActivityFrame>=clip.Spec.airborneStart&&c.Skin.Motion.ActivityFrame<=clip.Spec.airborneEnd;Observe(c,target);}Assert(seenAir&&c.Skin.Motion.HoldingPose&&c.Skin.Motion.Clip.Spec.id=="sit","没有腾空或落地后丢失持续坐姿");});
        Check("羽毛移动出爪位时跳跃会扑空，不凭动作开始就加分",delegate{Start(c,target);Observe(c,new Point(290,-30));for(int i=0;i<600&&c.Skin.Motion.PostureActivity!=null;i++){Step(c,.01);Observe(c,new Point(290,-30));}Assert(c.Life.Play.Contacts==0&&!c.Life.Play.CompletedGame,"移开的羽毛仍被凭空抓到");});
        Check("羽毛留在实际前爪路径上才记录接触",delegate{Start(c,target);for(int i=0;i<600&&c.Skin.Motion.PostureActivity!=null;i++){Observe(c,target);Step(c,.01);}Assert(c.Life.Play.Contacts==1,"原生空中爪位未接通接触");});
        Check("腾空中放下玩具会按原速向前落地，不倒放或瞬切",delegate{var p=new MotionPlayer();p.ConfigureLibrary(c.Skin.Motions);var sitting=c.Skin.Motions.Clips["sit"];p.StartResidence(sitting,40);p.Tick(sitting.Spec.holdAt/sitting.Spec.fps);p.AttendToy(target);Assert(p.PlayJump(target),"无法开始打断样例");p.Tick((clip.Spec.airborneStart+2)/clip.Spec.fps);int before=p.ActivityFrame;p.Cancel();p.Tick(.1);Assert(p.PostureActivity=="sit-jump"&&p.ActivityFrame>=before+2&&p.ActivityFrame<=before+3,"腾空打断倒放、加速或硬切");int last=p.ActivityFrame;while(p.PostureActivity=="sit-jump"){p.Tick(.01);if(p.PostureActivity!=null){Assert(p.ActivityFrame>=last,"落地片段被倒放");last=p.ActivityFrame;}}Assert(last>=clip.Spec.airborneEnd,"落地之前删除了跳跃状态");});
        Check("头顶空间不足时不启动会被屏幕裁切的起跳",delegate{ToyInteractionTests.Pose(c,CatHabit.SitUp);double top=c.Pet.Top;c.Pet.Top=SystemParameters.WorkArea.Top-c.Pet.Surface.PetRect.Top-clip.Spec.jumpTop*c.Settings.Size/256+2;c.SelectTool(PetTool.Feather);for(int i=0;i<60;i++){Step(c,.02);Observe(c,new Point(target.X+Math.Sin(i)*15,target.Y));}Assert(c.Life.Play.Jumps==0,"头部空间不足仍起跳");c.Pet.Top=top;});
        Check("勿扰和专注不启动跳跃，隐藏后完成安全收尾",delegate{c.Mode(PetMode.Quiet);c.SelectTool(PetTool.Feather);Observe(c,target);Assert(!c.Life.Play.Active,"勿扰仍拿玩具");c.Mode(PetMode.Companion);c.Companion.StartFocus(30);c.SelectTool(PetTool.Feather);Assert(!c.Life.Play.Active,"专注仍起跳");c.Companion.CancelFocus();Start(c,target);c.ToggleHidden();for(int i=0;i<700&&c.Skin.Motion.Active;i++)Step(c,.01);Assert(!c.Skin.Motion.Active&&c.Hidden,"隐藏时安全收尾未完成");c.ToggleHidden();});
        Check("最大桌宠尺寸下整只跳跃猫仍在实际透明窗口内",delegate{double size=c.Settings.Size;c.Settings.Size=240;var r=c.Pet.Surface.PetRect;foreach(var f in clip.Frames){Rect ink=Ink(f);double x=r.Left+(ink.Left+clip.Spec.originX)*240/256,y=r.Top+(ink.Top+clip.Spec.originY)*240/256,right=r.Left+(ink.Right+clip.Spec.originX)*240/256,bottom=r.Top+(ink.Bottom+clip.Spec.originY)*240/256;Assert(x>=0&&y>=0&&right<=c.Pet.Width&&bottom<=c.Pet.Height,"跳跃猫咪被窗口边界裁掉");}c.Settings.Size=size;});
        c.Pet.Close();c.Dispose();using(var f=File.Create(Path.Combine(output,"jump-test-report.json")))new DataContractJsonSerializer(typeof(LivingReport)).WriteObject(f,report);return report.failed==0?0:1;
    }
    public static int Preview(string manifest,string output){
        Directory.CreateDirectory(output);Directory.CreateDirectory(Path.Combine(output,"frames"));PetSettings.UsePreviewProfile(Path.Combine(output,"isolated-state"));var app=new Application();var c=ToyInteractionTests.Create(manifest);ToyInteractionTests.Pose(c,CatHabit.SitUp);c.SelectTool(PetTool.Feather);Point goal=Goal(c.Skin.Motions.Clips["sit-jump"]);
        for(int i=0;i<288;i++){double t=i/12.0;for(int sub=0;sub<5;sub++){double now=t+sub/60.0;Point at=now<1||now>=7&&now<12?new Point(95,175):now>12.6?new Point(290,goal.Y):new Point(goal.X+Math.Sin(now*9)*10,goal.Y);Observe(c,at);Step(c,1.0/60);}ToyInteractionTests.Render(c,Path.Combine(output,"frames","frame-"+i.ToString("D5")+".png"),t<7?"举高羽毛：起跳、扑抓、落地":"再次举高后移开：可以扑空");}
        File.WriteAllText(Path.Combine(output,"metrics.json"),"{\"jumps\":"+c.Life.Play.Jumps+",\"contacts\":"+c.Life.Play.Contacts+",\"software_input_simulation\":true}");c.Pet.Close();c.Dispose();return 0;
    }
}
}
